import 'package:firebase_core/firebase_core.dart';

import '../core/platform/crash_reporter.dart';
import '../firebase_options.dart' as dev_and_staging;
import '../firebase_options_prod.dart' as production;
import 'environment.dart';

/// Which Firebase project each build talks to (owner decision, 18 Oct 2026):
/// dev and staging use `baitalebdaa-76046`; production uses the separate `baitalebdaa`
/// project, so real customer data never mixes with test data.
///
/// `lib/firebase_options.dart` and `lib/firebase_options_prod.dart` are generated by
/// `flutterfire configure`; never edit them by hand.
FirebaseOptions? firebaseOptionsFor(AppFlavor flavor) => switch (flavor) {
  AppFlavor.dev || AppFlavor.stg => dev_and_staging.DefaultFirebaseOptions.currentPlatform,
  AppFlavor.prod => production.DefaultFirebaseOptions.currentPlatform,
};

/// Starts Firebase for this build. Returns false (and the app runs without Firebase) when
/// the build has no project or the platform has no configuration (web, until a web app is
/// registered). A failure here must never stop the app from opening.
Future<bool> initializeFirebase(AppEnvironment environment, CrashReporter crashReporter) async {
  try {
    final options = firebaseOptionsFor(environment.flavor);
    if (options == null) return false;
    await Firebase.initializeApp(options: options);
    return true;
  } on UnsupportedError {
    return false;
  } on Object catch (error, stack) {
    await crashReporter.recordError(error, stack);
    return false;
  }
}
